with cleaned as (select id, name, email, segment, signup_date, is_active, credit_limit, age, length(country) as country_length, credit_limit * age as credit_limit_times_age, coalesce(segment, 'N/A') as segment_filled from customers where segment is not null and segment in ('SMB', 'Consumer', 'Corporate')) select s.id, s.segment, s.signup_date, s.credit_limit, s.credit_limit_times_age, s.segment_filled, x.session_device, x.session_country from cleaned s left join lateral (select c.device as session_device, c.country as session_country from sessions c where c.customer_id = s.id and c.started_at <= s.signup_date order by c.started_at desc, c.id desc limit 1) x on true;
